"""Mutant-driven tests: M024 only changes the unspecified format of payment ids."""
from hypothesis import given, settings, strategies as st

from solution import Service


class Clock:
    def now(self):
        return 1000.0


class Gateway:
    def charge(self, reference, amount_cents):
        return "ok"


@settings(max_examples=30, deadline=None)
@given(amounts=st.lists(st.integers(1, 1000000), min_size=1, max_size=10))
def test_prop_payment_ids_are_strings_and_distinct(amounts):
    """Distinct payments recorded for a caller are returned as separate records, each with a string id that is not shared."""
    svc = Service(Clock(), Gateway())
    assert svc.register("alice", "password1")[0] == 201
    tok = svc.login("alice", "password1")[1]["token"]
    for i, amt in enumerate(amounts):
        out = svc.pay(tok, amt, f"key-{i}")
        assert out[0] == 201, f"input={(amt, i)!r} output={out!r}"
    out = svc.list_payments(tok)
    assert out[0] == 200 and len(out[1]) == len(amounts), f"amounts={amounts!r} output={out!r}"
    ids = [p["id"] for p in out[1]]
    assert all(isinstance(i, str) for i in ids), f"amounts={amounts!r} ids={ids!r}"
    assert len(set(ids)) == len(ids), f"amounts={amounts!r} ids={ids!r}"
    assert [p["amount_cents"] for p in out[1]] == amounts, f"amounts={amounts!r} output={out!r}"

