import pytest
from hypothesis import given, settings, strategies as st

from solution import Service
from gateway import GatewayTimeout


class FakeClock:
    def __init__(self, t=1000.0):
        self.t = float(t)

    def now(self):
        return self.t


class FakeGateway:
    def __init__(self):
        self.charged = {}
        self.calls = []

    def charge(self, reference, amount_cents):
        self.calls.append((reference, amount_cents))
        self.charged.setdefault(reference, amount_cents)
        return {"reference": reference, "amount_cents": amount_cents}


def setup(ttl=100):
    clock = FakeClock()
    gw = FakeGateway()
    svc = Service(clock, gw, token_ttl=ttl)
    assert svc.register("alice", "password1")[0] == 201
    return svc, clock, gw


def login(svc):
    s, body = svc.login("alice", "password1")
    assert s == 200, f"input=login output={(s, body)!r}"
    return body["token"]


def bad_token(svc, clock, kind):
    """Return a token in the requested invalid state."""
    if kind == "none":
        return None
    if kind == "unknown":
        return "no-such-token"
    if kind == "revoked":
        tok = login(svc)
        assert svc.logout(tok)[0] == 204
        return tok
    if kind == "expired":
        tok = login(svc)
        clock.t += 100
        return tok
    raise ValueError(kind)


KINDS = ["none", "unknown", "revoked", "expired"]


@pytest.mark.parametrize("kind", KINDS)
def test_pay_with_invalid_token_returns_401(kind):
    """pay with a missing, unknown, expired or revoked token returns 401 and charges nothing."""
    svc, clock, gw = setup()
