    """get_document with a missing, unknown, expired or revoked token returns 401, for existing and nonexistent ids."""
    svc, clock, gw = setup()
    owner_tok = login(svc)
    s, body = svc.create_document(owner_tok, "title", "content")
    assert s == 201, f"input=create output={(s, body)!r}"
    doc_id = body["id"]
    tok = bad_token(svc, clock, kind)
    for target in (doc_id, "no-such-document"):
        out = svc.get_document(tok, target)
        assert out[0] == 401, f"input=(get_document, {kind}, {target!r}) output={out!r}"


