"""Document and payment service."""
import copy
import hashlib
import hmac
import re
import secrets
import threading

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover
    class GatewayTimeout(Exception):
        pass

_USERNAME_RE = re.compile(r"[a-z0-9_]{3,32}")


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._lock = threading.RLock()
        self._users = {}        # username -> (salt, hash)
        self._tokens = {}       # token -> (username, created)
        self._docs = {}         # doc_id -> (seq, doc dict)
        self._user_docs = {}    # username -> [doc_id, ...] in creation order
        self._doc_counter = 0
        self._cursors = {}      # cursor -> (username, last_seq)
        self._payments = {}     # username -> [payment, ...]
        self._pay_by_key = {}   # (username, key) -> payment
        self._pay_attempt = {}  # (username, key) -> amount (attempted)
        self._pay_counter = 0

    # ---------- helpers ----------
    @staticmethod
    def _hash(salt, password):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 10000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if self._clock.now() < created + self._ttl:
            return user
        del self._tokens[token]
        return None

    @staticmethod
    def _valid_title(title):
        return isinstance(title, str) and 1 <= len(title) <= 200

    @staticmethod
    def _valid_content(content):
        return isinstance(content, str) and len(content) <= 100000

    def _find_doc(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        entry = self._docs.get(doc_id)
        if entry is None or entry[1]["owner"] != user:
            return None
        return entry

    def _user_doc_entries(self, user):
        return [self._docs[i] for i in self._user_docs.get(user, [])]

    # ---------- auth ----------
    def register(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
                return 400, None
            if not isinstance(password, str) or len(password) < 8:
                return 400, None
            if username in self._users:
                return 409, None
            salt = secrets.token_bytes(16)
            self._users[username] = (salt, self._hash(salt, password))
            return 201, None

    def login(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not isinstance(password, str):
                return 401, None
            rec = self._users.get(username)
            if rec is None:
                return 401, None
            salt, h = rec
            if not hmac.compare_digest(h, self._hash(salt, password)):
                return 401, None
            token = secrets.token_hex(24)
            self._tokens[token] = (username, self._clock.now())
            return 200, {"token": token}

    def logout(self, token):
        with self._lock:
            if self._auth(token) is None:
                return 401, None
            del self._tokens[token]
            return 204, None

    # ---------- documents ----------
    def create_document(self, token, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not self._valid_title(title) or not self._valid_content(content):
                return 400, None
            self._doc_counter += 1
            seq = self._doc_counter
            doc = {"id": "doc-%d" % seq, "owner": user, "title": title,
                   "content": content, "created_at": self._clock.now()}
            self._docs[doc["id"]] = (seq, doc)
            self._user_docs.setdefault(user, []).append(doc["id"])
            return 201, {"id": doc["id"]}

    def get_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            entry = self._find_doc(user, doc_id)
            if entry is None:
                return 404, None
            return 200, dict(entry[1])

    def update_document(self, token, doc_id, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            entry = self._find_doc(user, doc_id)
            if entry is None:
                return 404, None
            if not self._valid_title(title) or not self._valid_content(content):
                return 400, None
            entry[1]["title"] = title
            entry[1]["content"] = content
            return 200, dict(entry[1])

    def delete_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            entry = self._find_doc(user, doc_id)
            if entry is None:
                return 404, None
            del self._docs[doc_id]
            self._user_docs[user].remove(doc_id)
            return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(page_size) or not 1 <= page_size <= 100:
                return 400, None
            last_seq = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    return 400, None
                info = self._cursors.get(cursor)
                if info is None or info[0] != user:
                    return 400, None
                last_seq = info[1]
            remaining = [e for e in self._user_doc_entries(user) if e[0] > last_seq]
            page = remaining[:page_size]
            next_cursor = None
            if len(remaining) > page_size:
                next_cursor = secrets.token_hex(16)
                self._cursors[next_cursor] = (user, page[-1][0])
            return 200, {"items": [dict(e[1]) for e in page],
                         "next_cursor": next_cursor}

    def search_documents(self, token, query):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not isinstance(query, str) or query == "":
                return 400, None
            q = query.casefold()
            res = []
            for _, doc in self._user_doc_entries(user):
                if q in doc["title"].casefold() or q in doc["content"].casefold():
                    res.append(dict(doc))
            return 200, res

    def export_documents(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(d) for _, d in self._user_doc_entries(user)]

    # ---------- payments ----------
    def pay(self, token, amount_cents, idempotency_key):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(amount_cents) or not 1 <= amount_cents <= 1000000:
                return 400, None
            if not isinstance(idempotency_key, str):
                return 400, None
            k = (user, idempotency_key)
            existing = self._pay_by_key.get(k)
            if existing is not None:
                if existing["amount_cents"] == amount_cents:
                    return 200, dict(existing)
                return 409, None
            attempted = self._pay_attempt.get(k)
            if attempted is not None and attempted != amount_cents:
                return 409, None
            self._pay_attempt[k] = amount_cents
            reference = "%s:%s" % (user, idempotency_key)
            try:
                self._gateway.charge(reference, amount_cents)
            except GatewayTimeout:
                return 504, None
            self._pay_counter += 1
            payment = {"id": "pay-%d" % self._pay_counter,
                       "amount_cents": amount_cents,
                       "idempotency_key": idempotency_key,
                       "created_at": self._clock.now()}
            self._pay_by_key[k] = payment
            self._payments.setdefault(user, []).append(payment)
            return 201, dict(payment)

    def list_payments(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(p) for p in self._payments.get(user, [])]
