                return 404, None
            del self._docs[doc_id]
            self._user_docs[user].remove(doc_id)
            return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(page_size) or not 1 <= page_size <= 100:
                return 400, None
            last_seq = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    return 400, None
                info = self._cursors.get(cursor)
                if info is None or info[0] != user:
                    return 400, None
                last_seq = info[1]
            remaining = [e for e in self._user_doc_entries(user) if e[0] > last_seq]
            page = remaining[:page_size]
            next_cursor = None
            if len(remaining) > page_size:
                next_cursor = secrets.token_hex(16)
                self._cursors[next_cursor] = (user, page[-1][0])
            return 200, {"items": [dict(e[1]) for e in page],
                         "next_cursor": next_cursor}

    def search_documents(self, token, query):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not isinstance(query, str) or query == "":
                return 400, None
            q = query.casefold()
            res = []
            for _, doc in self._user_doc_entries(user):
                if q in doc["title"].casefold() or q in doc["content"].casefold():
                    res.append(dict(doc))
            return 200, res

    def export_documents(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(d) for _, d in self._user_doc_entries(user)]

    # ---------- payments ----------
    def pay(self, token, amount_cents, idempotency_key):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(amount_cents) or not 1 <= amount_cents <= 1000000:
                return 400, None
            if not isinstance(idempotency_key, str):
                return 400, None
            k = (user, idempotency_key)
            existing = self._pay_by_key.get(k)
            if existing is not None:
                if existing["amount_cents"] == amount_cents:
                    return 200, dict(existing)
                return 409, None
            attempted = self._pay_attempt.get(k)
            if attempted is not None and attempted != amount_cents:
                return 409, None
            self._pay_attempt[k] = amount_cents
            reference = "%s:%s" % (user, idempotency_key)
            try:
                self._gateway.charge(reference, amount_cents)
            except Exception as exc:
                if _is_timeout(exc):
                    return 504, None
                raise
            self._pay_counter += 1
            payment = {"id": "pay-%d" % self._pay_counter,
                       "amount_cents": amount_cents,
                       "idempotency_key": idempotency_key,
                       "created_at": self._clock.now()}
            self._pay_by_key[k] = payment
            self._payments.setdefault(user, []).append(payment)
            return 201, dict(payment)

    def list_payments(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(p) for p in self._payments.get(user, [])]
